mapper.select:
SELECT todo_id AS todo_id, user_id AS user_id, title, content, schedule_date AS schedule_date, is_checked AS is_checked, file_url AS file_url FROM todo WHERE user_id = #{user_id}
AND title LIKE '%' || #{keyword} || '%'
ORDER BY schedule_date ASC OFFSET #{offset} ROWS FETCH NEXT #{amount} ROWS ONLY

mapper.update:
UPDATE todo
SET title = #{title},
    content = #{content},
    schedule_date = #{schedule_date},
    is_checked = #{is_checked}
WHERE todo_id = #{todo_id}
